export const getGetRecordingShareUrl = (shareId: string,
    params?: GetRecordingShareParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/r/${encodeURIComponent(String(shareId))}?${stringifiedParams}` : `/r/${encodeURIComponent(String(shareId))}`
}

